  downloads INTEGER DEFAULT 0,
  votes INTEGER DEFAULT 0,
  globs TEXT[] DEFAULT '{}',
  tags TEXT[] DEFAULT '{}',
  examples JSONB DEFAULT '{}'::JSONB,
  compatibility JSONB DEFAULT '{"ides": [], "aiAssistants": [], "frameworks": [], "mcpServers": []}'::JSONB,
  always_apply BOOLEAN DEFAULT FALSE,
  frontmatter JSONB DEFAULT '{}',
  subcategory TEXT,
  framework TEXT,
  language TEXT,
  stack TEXT,
  complexity TEXT CHECK (complexity IN ('simple', 'medium', 'complex')),
  scope TEXT CHECK (scope IN ('file', 'component', 'feature', 'project', 'system')),
  audience TEXT CHECK (audience IN ('developer', 'architect', 'team-lead', 'junior', 'senior', 'any')),
  maturity TEXT CHECK (maturity IN ('experimental', 'beta', 'stable', 'deprecated')),
  repository_url TEXT,
  license TEXT,
  schema_version TEXT DEFAULT '2.1.0',
  content_sections JSONB DEFAULT '[]',
  author TEXT DEFAULT 'community',
  contributors TEXT[] DEFAULT '{}',
  discussion_url TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  last_updated TIMESTAMPTZ DEFAULT NOW()
);

