CREATE TABLE IF NOT EXISTS public.commands (
  id TEXT PRIMARY KEY, -- Uses kebab-case command ID from schema
  name TEXT NOT NULL,
  description TEXT NOT NULL CHECK (char_length(description) >= 10 AND char_length(description) <= 200),
  target TEXT NOT NULL DEFAULT 'claude-code' CHECK (target IN ('claude-code')),
  command_type TEXT NOT NULL CHECK (command_type IN ('slash', 'custom-slash', 'mcp', 'workflow', 'hook')),
  version TEXT CHECK (version ~ '^\d+\.\d+\.\d+$'),
  scope TEXT DEFAULT 'project' CHECK (scope IN ('user', 'project', 'global')),
  permissions JSONB DEFAULT '{}',
  claude_code_config JSONB DEFAULT '{}',
  examples JSONB DEFAULT '[]',
  installation JSONB DEFAULT '{}',
  tags TEXT[] DEFAULT '{}',
  category TEXT CHECK (category IN ('development', 'testing', 'debugging', 'refactoring', 'documentation', 'git', 'analysis', 'security', 'performance')),
  author TEXT,
  last_updated DATE,
  compatibility_notes TEXT,
  blueprint_id TEXT REFERENCES public.blueprints(id) ON DELETE SET NULL,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT valid_name_length CHECK (char_length(name) >= 1 AND char_length(name) <= 50),
  CONSTRAINT valid_id_format CHECK (id ~ '^[a-z0-9-]+$')
);

