  platform_type TEXT NOT NULL CHECK (platform_type IN (
    'claude-code', 'claude-desktop', 'cursor', 'windsurf', 'windsurf-next', 'github-copilot',
    'zed', 'vscode', 'vscode-insiders', 'vscodium', 'jetbrains', 'intellij', 'webstorm',
    'pycharm', 'phpstorm', 'rubymine', 'clion', 'datagrip', 'goland', 'rider',
    'android-studio', 'openai', 'generic-ai'
  )),
  platform_config JSONB NOT NULL DEFAULT '{}',
  is_compatible BOOLEAN DEFAULT true,
  priority INTEGER DEFAULT 5 CHECK (priority >= 1 AND priority <= 10),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(blueprint_id, platform_type)
);

CREATE TABLE IF NOT EXISTS public.platform_commands (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  blueprint_id TEXT REFERENCES public.blueprints(id) ON DELETE CASCADE,
  platform_type TEXT NOT NULL CHECK (platform_type IN (
    'claude-code', 'claude-desktop', 'cursor', 'windsurf', 'windsurf-next', 'github-copilot',
    'zed', 'vscode', 'vscode-insiders', 'vscodium', 'jetbrains', 'intellij', 'webstorm',
    'pycharm', 'phpstorm', 'rubymine', 'clion', 'datagrip', 'goland', 'rider',
    'android-studio', 'openai', 'generic-ai'
  )),
  command_name TEXT NOT NULL,
  command_content TEXT NOT NULL,
  command_metadata JSONB DEFAULT '{}',
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(blueprint_id, platform_type, command_name)
);

CREATE TABLE IF NOT EXISTS public.blueprint_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  blueprint_id TEXT REFERENCES public.blueprints(id) ON DELETE CASCADE,
  version TEXT NOT NULL,
  content TEXT NOT NULL,
  changes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE OR REPLACE VIEW cli_deployment_summary AS
SELECT
    d.deployment_id,
    d.project_name,
    d.team_name,
    d.blueprints_count,
    d.deployed_at,
    d.project_signature,
    COUNT(r.id) as actual_blueprints_stored,
    COALESCE(SUM(r.blueprint_size), 0) as total_blueprints_size
FROM cli_deployments d
LEFT JOIN cli_deployment_blueprints r ON d.deployment_id = r.deployment_id
GROUP BY d.deployment_id, d.project_name, d.team_name, d.blueprints_count, d.deployed_at, d.project_signature
ORDER BY d.deployed_at DESC;

CREATE TABLE IF NOT EXISTS public.collection_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  collection_id UUID REFERENCES public.collections(id) ON DELETE CASCADE,
  blueprint_id TEXT REFERENCES public.blueprints(id) ON DELETE CASCADE,
  added_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(collection_id, blueprint_id),
    command_id TEXT REFERENCES commands(id) ON DELETE CASCADE,
    item_type TEXT GENERATED ALWAYS AS ( CASE WHEN blueprint_id IS NOT NULL THEN 'blueprint' WHEN command_id IS NOT NULL THEN 'command' ELSE NULL END ) STORED,
    CONSTRAINT collection_items_item_type_check CHECK ( (blueprint_id IS NOT NULL AND command_id IS NULL) OR (blueprint_id IS NULL AND command_id IS NOT NULL) )
);

CREATE OR REPLACE VIEW public.command_search_view AS
SELECT 
  c.*,
  b.title as blueprint_title,
  b.slug as blueprint_slug,
  cat.name as blueprint_category
FROM public.commands c
LEFT JOIN public.blueprints b ON c.blueprint_id = b.id
LEFT JOIN public.categories cat ON b.category_id = cat.id
WHERE c.is_active = true;

CREATE OR REPLACE VIEW collection_contents AS
SELECT 
  ci.id,
  ci.collection_id,
  ci.added_at,
  ci.item_type,
  ci.blueprint_id,
  ci.command_id,
  COALESCE(b.title, c.name) as item_name,
  COALESCE(b.description, c.description) as item_description,
  COALESCE(b.slug, c.id) as item_slug,
  b.category_id as blueprint_category_id,
  c.category as command_category,
  c.command_type,
  c.scope as command_scope
FROM collection_items ci
LEFT JOIN blueprints b ON ci.blueprint_id = b.id
LEFT JOIN commands c ON ci.command_id = c.id;


-- === FUNCTIONS OBJECTS ===

CREATE OR REPLACE FUNCTION trigger_set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION upsert_user_blueprint_usage(
    p_user_id UUID,
    p_blueprint_id TEXT
)
RETURNS void AS $$
BEGIN
    INSERT INTO user_blueprint_usage (user_id, blueprint_id, usage_count, last_used)
    VALUES (p_user_id, p_blueprint_id, 1, CURRENT_TIMESTAMP)
    ON CONFLICT (user_id, blueprint_id)
    DO UPDATE SET
        usage_count = user_blueprint_usage.usage_count + 1,
        last_used = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_blueprint_relationships(
  blueprint_id TEXT,
  relationship_types TEXT[] DEFAULT '{"requires", "suggests", "conflicts", "supersedes", "enhances"}'
)
RETURNS TABLE (
  relationship_type TEXT,
  related_blueprint jsonb,
  condition_tags jsonb,
  condition_platforms TEXT[],
  condition_stack TEXT,
  priority INTEGER
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    rr.relationship_type,
    to_jsonb(related_blueprint.*) as related_blueprint,
    rr.condition_tags,
    rr.condition_platforms,
    rr.condition_stack,
    rr.priority
  FROM public.blueprint_relationships rr
  JOIN public.blueprints related_blueprint ON rr.related_blueprint_id = related_blueprint.id
  WHERE rr.blueprint_id = blueprint_id
    AND rr.relationship_type = ANY(relationship_types)
  ORDER BY rr.priority DESC, rr.relationship_type;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_blueprint_for_platform(
  blueprint_id TEXT,
  platform TEXT
)
RETURNS TABLE (
  blueprint_data jsonb,
  platform_config jsonb,
  commands jsonb
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    to_jsonb(r.*) as blueprint_data,
    COALESCE(rp.platform_config, '{}'::jsonb) as platform_config,
    COALESCE(
      (SELECT jsonb_agg(
        jsonb_build_object(
          'name', pc.command_name,
          'content', pc.command_content,
          'metadata', pc.command_metadata
        )
      ) FROM public.platform_commands pc
      WHERE pc.blueprint_id = r.id AND pc.platform_type = platform AND pc.is_active = true),
      '[]'::jsonb
    ) as commands
  FROM public.blueprints r
  LEFT JOIN public.blueprint_platforms rp ON r.id = rp.blueprint_id AND rp.platform_type = platform
  WHERE r.id = blueprint_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.remove_blueprint_vote(target_blueprint_id TEXT)
RETURNS VOID AS $$
BEGIN
  DELETE FROM public.user_votes
  WHERE user_id = auth.uid() AND blueprint_id = target_blueprint_id;
  UPDATE public.blueprints
  SET votes = (SELECT COUNT(*) FROM public.user_votes WHERE user_votes.blueprint_id = target_blueprint_id)
  WHERE id = target_blueprint_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_blueprints_by_category(category_slug TEXT)
RETURNS SETOF public.blueprints AS $$
BEGIN
  RETURN QUERY
  SELECT r.*
  FROM public.blueprints r
  JOIN public.categories c ON r.category_id = c.id
  WHERE c.slug = category_slug
  ORDER BY r.votes DESC, r.downloads DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.validate_blueprint_schema(
  blueprint_id TEXT,
  schema_version TEXT DEFAULT '2.0.0'
)
RETURNS jsonb AS $$
DECLARE
  blueprint_record public.blueprints;
  validation_result jsonb;
  errors jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO blueprint_record FROM public.blueprints WHERE id = blueprint_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'errors', jsonb_build_array('Blueprint not found')
    );
  END IF;
  IF blueprint_record.title IS NULL OR trim(blueprint_record.title) = '' THEN
    errors := errors || jsonb_build_array('Title is required');
  END IF;
  IF blueprint_record.description IS NULL OR trim(blueprint_record.description) = '' THEN
    errors := errors || jsonb_build_array('Description is required');
  END IF;
  IF blueprint_record.content IS NULL OR trim(blueprint_record.content) = '' THEN
    errors := errors || jsonb_build_array('Content is required');
  END IF;
  IF blueprint_record.complexity IS NOT NULL AND blueprint_record.complexity NOT IN ('simple', 'medium', 'complex') THEN
    errors := errors || jsonb_build_array('Invalid complexity value');
  END IF;
  IF blueprint_record.scope IS NOT NULL AND blueprint_record.scope NOT IN ('file', 'component', 'feature', 'project', 'system') THEN
    errors := errors || jsonb_build_array('Invalid scope value');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.blueprint_platforms WHERE blueprint_id = blueprint_record.id) THEN
    warnings := warnings || jsonb_build_array('No platform compatibility defined');
  END IF;
  validation_result := jsonb_build_object(
    'status', CASE
      WHEN jsonb_array_length(errors) > 0 THEN 'error'
      WHEN jsonb_array_length(warnings) > 0 THEN 'warning'
      ELSE 'valid'
    END,
    'errors', errors,
    'warnings', warnings,
    'validated_at', NOW()
  );
  INSERT INTO public.blueprint_validations (blueprint_id, schema_version, validation_status, validation_errors, validation_warnings)
  VALUES (blueprint_id, schema_version, (validation_result->>'status'), errors, warnings)
  ON CONFLICT (blueprint_id, schema_version)
  DO UPDATE SET
    validation_status = EXCLUDED.validation_status,
    validation_errors = EXCLUDED.validation_errors,
    validation_warnings = EXCLUDED.validation_warnings,
    validated_at = NOW();
  RETURN validation_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION upsert_user_platform_stats(
    p_user_id UUID,
    p_platform TEXT
)
RETURNS void AS $$
BEGIN
    INSERT INTO user_platform_stats (user_id, platform, usage_count, last_used)
    VALUES (p_user_id, p_platform, 1, CURRENT_TIMESTAMP)
    ON CONFLICT (user_id, platform)
    DO UPDATE SET
        usage_count = user_platform_stats.usage_count + 1,
        last_used = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_popular_blueprints(limit_count INTEGER DEFAULT 10)
RETURNS SETOF public.blueprints AS $$
BEGIN
  RETURN QUERY
  SELECT r.*
  FROM public.blueprints r
  ORDER BY
    (r.votes * 2 + r.downloads) DESC,
    r.created_at DESC
  LIMIT limit_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.search_blueprints_enhanced(
  search_query TEXT DEFAULT NULL,
  category_slug TEXT DEFAULT NULL,
  tags TEXT[] DEFAULT '{}',
  platforms TEXT[] DEFAULT '{}',
  complexity TEXT DEFAULT NULL,
  scope TEXT DEFAULT NULL,
  audience TEXT DEFAULT NULL,
  maturity TEXT DEFAULT NULL,
  framework TEXT DEFAULT NULL,
  language TEXT DEFAULT NULL,
  stack TEXT DEFAULT NULL
)
RETURNS SETOF public.blueprints AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT r.*
  FROM public.blueprints r
  LEFT JOIN public.categories c ON r.category_id = c.id
  LEFT JOIN public.blueprint_platforms rp ON r.id = rp.blueprint_id
  WHERE
    (search_query IS NULL OR
     to_tsvector('english', r.title || ' ' || r.description || ' ' || r.content) @@ plainto_tsquery('english', search_query)) AND
    (category_slug IS NULL OR c.slug = category_slug) AND
    (array_length(tags, 1) IS NULL OR r.tags && tags) AND
    (array_length(platforms, 1) IS NULL OR EXISTS (
      SELECT 1 FROM public.blueprint_platforms rp2
      WHERE rp2.blueprint_id = r.id AND rp2.platform_type = ANY(platforms) AND rp2.is_compatible = true
    )) AND
    (complexity IS NULL OR r.complexity = complexity) AND
    (scope IS NULL OR r.scope = scope) AND
    (audience IS NULL OR r.audience = audience) AND
    (maturity IS NULL OR r.maturity = maturity) AND
    (framework IS NULL OR r.framework = framework) AND
    (language IS NULL OR r.language = language) AND
    (stack IS NULL OR r.stack = stack)
  ORDER BY
    CASE WHEN search_query IS NOT NULL
    THEN ts_rank(to_tsvector('english', r.title || ' ' || r.description || ' ' || r.content), plainto_tsquery('english', search_query))
    ELSE 0 END DESC,
    r.votes DESC,
    r.downloads DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION get_cli_usage_summary(
  start_date TIMESTAMP WITH TIME ZONE DEFAULT NOW() - INTERVAL '30 days',
  end_date TIMESTAMP WITH TIME ZONE DEFAULT NOW()
)
RETURNS TABLE (
  total_events BIGINT,
  success_rate NUMERIC,
  avg_execution_time_ms NUMERIC,
  unique_sessions BIGINT,
  top_commands JSONB,
  platform_distribution JSONB
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*) as total_events,
    (COUNT(*) FILTER (WHERE success = true))::NUMERIC / NULLIF(COUNT(*), 0) * 100 as success_rate,
    AVG(execution_time_ms) as avg_execution_time_ms,
    COUNT(DISTINCT session_id) as unique_sessions,
    (
      SELECT jsonb_agg(
        jsonb_build_object('command', command, 'count', count)
      )
      FROM (
        SELECT command, COUNT(*) as count
        FROM cli_usage_events
        WHERE timestamp BETWEEN start_date AND end_date
        GROUP BY command
        ORDER BY count DESC
        LIMIT 10
      ) top_cmds
    ) as top_commands,
    (
      SELECT jsonb_agg(
        jsonb_build_object('platform', platform, 'count', count)
      )
      FROM (
        SELECT platform, COUNT(*) as count
        FROM cli_usage_events
        WHERE timestamp BETWEEN start_date AND end_date
        GROUP BY platform
        ORDER BY count DESC
      ) platforms
    ) as platform_distribution
  FROM cli_usage_events
  WHERE timestamp BETWEEN start_date AND end_date;
END;
$$;

CREATE OR REPLACE FUNCTION upsert_user_command_stats(
    p_user_id UUID,
    p_command TEXT
)
RETURNS void AS $$
BEGIN
    INSERT INTO user_command_stats (user_id, command, usage_count, last_used)
    VALUES (p_user_id, p_command, 1, CURRENT_TIMESTAMP)
    ON CONFLICT (user_id, command)
    DO UPDATE SET
        usage_count = user_command_stats.usage_count + 1,
        last_used = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_table_stats()
RETURNS TABLE (
  table_name TEXT,
  row_count BIGINT,
  size_bytes BIGINT
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    schemaname || '.' || tablename as table_name,
    COALESCE(n_tup_ins - n_tup_del, 0) as row_count,
    COALESCE(pg_total_relation_size(schemaname||'.'||tablename), 0) as size_bytes
  FROM pg_stat_user_tables
  WHERE schemaname = 'public'
  ORDER BY pg_total_relation_size(schemaname||'.'||tablename) DESC NULLS LAST;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION trigger_update_blueprint_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  IF OLD.content IS DISTINCT FROM NEW.content THEN
    NEW.last_updated = NOW();
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.vote_for_blueprint(target_blueprint_id TEXT)
RETURNS VOID AS $$
BEGIN
  INSERT INTO public.user_votes (user_id, blueprint_id)
  VALUES (auth.uid(), target_blueprint_id)
  ON CONFLICT (user_id, blueprint_id) DO NOTHING;
  UPDATE public.blueprints
  SET votes = (SELECT COUNT(*) FROM public.user_votes WHERE user_votes.blueprint_id = target_blueprint_id)
  WHERE id = target_blueprint_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.increment_blueprint_downloads(target_blueprint_id TEXT)
RETURNS VOID AS $$
BEGIN
  UPDATE public.blueprints
  SET downloads = downloads + 1
  WHERE id = target_blueprint_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION generate_api_token()
RETURNS TEXT AS $$
DECLARE
    token_length INTEGER := 64;
    chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    result TEXT := '';
    i INTEGER := 0;
BEGIN
    FOR i IN 1..token_length LOOP
        result := result || substring(chars, floor(random() * char_length(chars) + 1)::integer, 1);
    END LOOP;
    RETURN 'vdk_' || result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION trigger_sync_vote_count()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.blueprints
    SET votes = votes + 1
    WHERE id = NEW.blueprint_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.blueprints
    SET votes = votes - 1
    WHERE id = OLD.blueprint_id;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN auth.email() IN (SELECT email FROM public.admins);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION recalculate_blueprint_stats(blueprint_uuid UUID)
RETURNS VOID AS $$
DECLARE
  new_usage_count INTEGER;
  new_success_rate DECIMAL(3,2);
  new_rating DECIMAL(3,2);
  new_vote_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO new_usage_count
  FROM blueprint_usage
  WHERE blueprint_id = blueprint_uuid;
  SELECT 
    CASE 
      WHEN COUNT(*) = 0 THEN 0
      ELSE ROUND(COUNT(*) FILTER (WHERE success = true)::DECIMAL / COUNT(*), 2)
    END INTO new_success_rate
  FROM blueprint_usage
  WHERE blueprint_id = blueprint_uuid;
  SELECT 
    CASE 
      WHEN COUNT(*) FILTER (WHERE rating IS NOT NULL) = 0 THEN 0
      ELSE ROUND(AVG(rating), 2)
    END INTO new_rating
  FROM blueprint_votes
  WHERE blueprint_id = blueprint_uuid;
  SELECT COUNT(*) INTO new_vote_count
  FROM blueprint_votes
  WHERE blueprint_id = blueprint_uuid AND vote_type = 'up';
  UPDATE community_blueprints
  SET 
    usage_count = new_usage_count,
    deployment_success_rate = new_success_rate,
    rating = new_rating,
    vote_count = new_vote_count,
    updated_at = NOW()
  WHERE id = blueprint_uuid;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_cli_integration_summary(
  timeframe_days INTEGER DEFAULT 7
)
RETURNS TABLE (
  integration_type TEXT,
  total_events BIGINT,
  detections BIGINT,
  activations BIGINT,
  errors BIGINT,
  error_rate NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.integration_type,
    COUNT(*) as total_events,
    COUNT(*) FILTER (WHERE action = 'detected') as detections,
    COUNT(*) FILTER (WHERE action = 'activated') as activations,
    COUNT(*) FILTER (WHERE success = false) as errors,
    (COUNT(*) FILTER (WHERE success = false))::NUMERIC / NULLIF(COUNT(*), 0) * 100 as error_rate
  FROM cli_integration_events i
  WHERE timestamp >= NOW() - (timeframe_days || ' days')::INTERVAL
  GROUP BY i.integration_type
  ORDER BY total_events DESC;
END;
$$;

CREATE OR REPLACE FUNCTION validate_api_token(p_token TEXT)
RETURNS TABLE(user_id UUID, token_id UUID, is_valid BOOLEAN) AS $$
DECLARE
    found_user_id UUID;
    found_token_id UUID;
    is_expired BOOLEAN;
    is_active BOOLEAN;
BEGIN
    SELECT t.user_id, t.id, t.is_active, (t.expires_at < CURRENT_TIMESTAMP)
    INTO found_user_id, found_token_id, is_active, is_expired
    FROM user_api_tokens t
    WHERE (t.token_hash = p_token OR t.token_hash = crypt(p_token, t.token_hash))
      AND t.is_active = TRUE
      AND (t.expires_at IS NULL OR t.expires_at > CURRENT_TIMESTAMP)
    LIMIT 1;
    IF found_user_id IS NOT NULL AND NOT is_expired AND is_active THEN
        UPDATE user_api_tokens
        SET last_used = CURRENT_TIMESTAMP
        WHERE id = found_token_id;
        RETURN QUERY SELECT found_user_id, found_token_id, TRUE;
    ELSE
        RETURN QUERY SELECT NULL::UUID, NULL::UUID, FALSE;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.search_blueprints(
  search_query TEXT,
  category_slug TEXT DEFAULT NULL,
  tags TEXT[] DEFAULT '{}')
RETURNS SETOF public.blueprints AS $$
BEGIN
  RETURN QUERY
  SELECT r.*
  FROM public.blueprints r
  LEFT JOIN public.categories c ON r.category_id = c.id
  WHERE
    (search_query IS NULL OR
     to_tsvector('english', r.title || ' ' || r.description || ' ' || r.content) @@ plainto_tsquery('english', search_query)) AND
    (category_slug IS NULL OR c.slug = category_slug) AND
    (array_length(tags, 1) IS NULL OR r.tags && tags)
  ORDER BY
    CASE WHEN search_query IS NOT NULL
    THEN ts_rank(to_tsvector('english', r.title || ' ' || r.description || ' ' || r.content), plainto_tsquery('english', search_query))
    ELSE 0 END DESC,
    r.votes DESC,
    r.downloads DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION increment_blueprint_usage(blueprint_id TEXT)
RETURNS void AS $$
BEGIN
    UPDATE blueprints
    SET downloads = COALESCE(downloads, 0) + 1,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = blueprint_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION create_user_api_token(
    p_user_id UUID,
    p_token_name TEXT DEFAULT 'CLI Token',
    p_expires_in_days INTEGER DEFAULT 365
)
RETURNS TABLE(token TEXT, token_id UUID, prefix TEXT) AS $$
DECLARE
    new_token TEXT;
    token_id UUID;
    token_prefix TEXT;
    token_hash TEXT;
BEGIN
    new_token := generate_api_token();
    token_prefix := LEFT(new_token, 8) || '...';
    BEGIN
        token_hash := crypt(new_token, gen_salt('bf'));
    EXCEPTION
        WHEN undefined_function THEN
            token_hash := new_token;
    END;
    INSERT INTO user_api_tokens (user_id, token_name, token_hash, token_prefix, expires_at)
    VALUES (
        p_user_id,
        p_token_name,
        token_hash,
        token_prefix,
        CURRENT_TIMESTAMP + (p_expires_in_days * INTERVAL '1 day')
    )
    RETURNING id INTO token_id;
    RETURN QUERY SELECT new_token, token_id, token_prefix;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION trigger_recalculate_stats_usage()
RETURNS TRIGGER AS $$
BEGIN
  PERFORM recalculate_blueprint_stats(NEW.blueprint_id);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_recalculate_stats_votes()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM recalculate_blueprint_stats(OLD.blueprint_id);
    RETURN OLD;
  ELSE
    PERFORM recalculate_blueprint_stats(NEW.blueprint_id);
    RETURN NEW;
  END IF;
END;
$$ LANGUAGE plpgsql;


-- === TRIGGERS OBJECTS ===

CREATE TRIGGER trigger_categories_set_updated_at
BEFORE UPDATE ON public.categories
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER trigger_commands_set_updated_at
BEFORE UPDATE ON public.commands
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER update_user_blueprint_usage_updated_at BEFORE UPDATE ON user_blueprint_usage
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_blueprints_set_updated_at
BEFORE UPDATE ON public.blueprints
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER update_user_project_stats_updated_at BEFORE UPDATE ON user_project_stats
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_user_command_stats_updated_at BEFORE UPDATE ON user_command_stats
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_vote_count_update
AFTER INSERT OR DELETE ON public.user_votes
FOR EACH ROW EXECUTE FUNCTION trigger_sync_vote_count();

CREATE TRIGGER update_vdk_versions_updated_at BEFORE UPDATE ON vdk_versions
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_team_configurations_updated_at BEFORE UPDATE ON team_configurations
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_profiles_set_updated_at
BEFORE UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER recalculate_stats_on_votes
  AFTER INSERT OR UPDATE OR DELETE ON blueprint_votes
  FOR EACH ROW EXECUTE FUNCTION trigger_recalculate_stats_votes();

CREATE TRIGGER update_cli_deployments_updated_at BEFORE UPDATE ON cli_deployments
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_user_api_tokens_updated_at BEFORE UPDATE ON user_api_tokens
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER recalculate_stats_on_usage
  AFTER INSERT ON blueprint_usage
  FOR EACH ROW EXECUTE FUNCTION trigger_recalculate_stats_usage();

CREATE TRIGGER trigger_blueprint_content_update
BEFORE UPDATE ON public.blueprints
FOR EACH ROW EXECUTE FUNCTION trigger_update_blueprint_timestamp();

CREATE TRIGGER update_user_platform_stats_updated_at BEFORE UPDATE ON user_platform_stats
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_collections_set_updated_at
BEFORE UPDATE ON public.collections
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER update_community_blueprints_updated_at 
  BEFORE UPDATE ON community_blueprints 
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_blueprint_platforms_set_updated_at
BEFORE UPDATE ON public.blueprint_platforms
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER trigger_platform_commands_set_updated_at
BEFORE UPDATE ON public.platform_commands
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();

CREATE TRIGGER update_blueprint_votes_updated_at 
  BEFORE UPDATE ON blueprint_votes 
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_generation_templates_set_updated_at
BEFORE UPDATE ON public.generation_templates
FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at();


