-- === SECURITY OBJECTS ===

CREATE POLICY "Users can update their own platform stats" ON user_platform_stats
    FOR UPDATE USING (auth.uid()::text = user_id::text);

CREATE POLICY "Public read access for votes" ON blueprint_votes
  FOR SELECT USING (true);

CREATE POLICY "Admins can manage all data" ON public.categories
FOR ALL USING (auth.email() IN (SELECT email FROM public.admins));

CREATE POLICY "Authenticated users can read profiles" ON public.profiles
FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Admins can manage platform commands" ON public.platform_commands
FOR ALL USING (auth.email() IN (SELECT email FROM public.admins));

CREATE POLICY "Service role full access on usage" ON blueprint_usage
  FOR ALL USING (auth.jwt() ->> 'role' = 'service_role');

CREATE POLICY "Authors can read their own blueprints" ON community_blueprints
  FOR SELECT USING (auth.uid() = author_id);

CREATE POLICY "Public read access for active commands" ON public.commands 
FOR SELECT USING (is_active = true);

CREATE POLICY "Users can update their own collection items with commands" ON collection_items
  FOR UPDATE USING (
    collection_id IN (
      SELECT id FROM collections WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Users can read public collections" ON public.collections
FOR SELECT USING (is_public = TRUE OR auth.uid() = user_id);

CREATE POLICY "Users can view their own command stats" ON user_command_stats
    FOR SELECT USING (auth.uid()::text = user_id::text);

CREATE POLICY "Public read access for categories" ON public.categories FOR SELECT USING (true);

CREATE POLICY "Users can insert their own team configurations" ON team_configurations
    FOR INSERT WITH CHECK (auth.uid()::text = user_id::text);

CREATE POLICY "Authenticated users can insert recommendations" ON cli_recommendations
    FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Anonymous users can read generated packages" ON public.generated_packages
FOR SELECT USING (true);

CREATE POLICY "Allow package cleanup" ON storage.objects
FOR DELETE USING (bucket_id = 'generated-packages');

CREATE POLICY "Users can update their own votes" ON blueprint_votes
  FOR UPDATE USING (auth.uid() = user_id);

