FOR ALL USING (EXISTS (SELECT 1 FROM public.collections c WHERE c.id = collection_id AND c.user_id = auth.uid()));

CREATE POLICY "Public read access for blueprint validations" ON public.blueprint_validations FOR SELECT USING (true);

CREATE POLICY "Admins can manage blueprint validations" ON public.blueprint_validations
FOR ALL USING (auth.email() IN (SELECT email FROM public.admins));

CREATE POLICY "Users can view their own API tokens" ON user_api_tokens
    FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can delete their own profiles" ON public.profiles
FOR DELETE USING (auth.uid() = id);

CREATE POLICY "Public read access for platform commands" ON public.platform_commands FOR SELECT USING (true);

CREATE POLICY "Service role can access all CLI usage events" ON cli_usage_events
  FOR ALL USING (auth.role() = 'service_role');

CREATE POLICY "Users can update their own API tokens" ON user_api_tokens
    FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Admins can manage all blueprints" ON public.blueprints
FOR ALL USING (auth.email() IN (SELECT email FROM public.admins));

CREATE POLICY "Allow updating download counts" ON public.generated_packages
FOR UPDATE USING (true)
WITH CHECK (true);

CREATE POLICY "Authenticated users can insert CLI performance events" ON cli_performance_events
  FOR INSERT WITH CHECK (auth.role() = 'authenticated' OR auth.role() = 'anon');

CREATE POLICY "Users can delete their own API tokens" ON user_api_tokens
    FOR DELETE USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own collection items with commands" ON collection_items
  FOR INSERT WITH CHECK (
    collection_id IN (
      SELECT id FROM collections WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Service role can access all CLI performance events" ON cli_performance_events
  FOR ALL USING (auth.role() = 'service_role');

CREATE POLICY "Anonymous users can create generated packages" ON public.generated_packages
FOR INSERT WITH CHECK (true);

CREATE POLICY "Authenticated users can insert CLI error events" ON cli_error_events
  FOR INSERT WITH CHECK (auth.role() = 'authenticated' OR auth.role() = 'anon');

CREATE POLICY "Users can update their own blueprint usage" ON user_blueprint_usage
    FOR UPDATE USING (auth.uid()::text = user_id::text);

CREATE POLICY "Public read access for blueprint versions" ON public.blueprint_versions FOR SELECT USING (true);

CREATE POLICY "Anyone can view version information" ON vdk_versions
    FOR SELECT USING (true);

CREATE POLICY "Users can manage their votes" ON public.user_votes
FOR ALL USING (auth.uid() = user_id);

